function belowMinimum(inventory: Inventory, minimum = 200): boolean {
    return inventory.beans < minimum;
  }

function* deliveryPlan(inventory: Inventory, target = 1000): Generator<Delivery> {
    function shortage(current: number): number {
      return Math.max(0, target - current);
    }
    if (shortage(inventory.beans)) yield { beans: shortage(inventory.beans) };
  }

function* (inventory: Inventory): Generator<string> {
    if (inventory.beans < 200) yield "Order beans";
    if (inventory.cups < 10) yield "Order cups";
  }

constructor(
    private readonly inventory: BeanInventory = new BeanInventory(),
    private readonly brewer: Brewer = new Brewer(),
    private readonly receipt: Receipt = new Receipt(),
  )

function buildOrder(id: string, customer: string, [first, ...others]: [OrderItem, ...OrderItem[]], note = ""): Order {
  return { id, customer, items: [first, ...others], note, status: "queued" };
}

function* expandTickets({ items }: Order): Generator<Ticket> {
  function ticket(name: string, index: number): Ticket {
    return { name, index, dose: Recipe.dose(name) };
  }
  for (const { name, quantity = 1 } of items) {
    for (let index = 0; index < quantity; index++) yield ticket(name, index);
  }
}

function* (orders: Order[], status: Order["status"] = "ready"): Generator<Order> {
  for (const order of orders) {
    if (order.status === status) yield order;
  }
}

function label(customer: string): string {
  return `pickup for ${customer}`;
}

function* schedulingQueue(orders: { customer: string; names: string[] }[]) {
  const total = ((names: string[]) => names.reduce((sum, name) => sum + scheduleDrink(name), 0));
  for (const order of orders) {
    yield { customer: order.customer, portions: total(order.names) };
  }
}

function labelPickup(order: Order) {
  function customerLabel() { return `${order.customer}: ${order.note || "counter"}`; }
  return customerLabel();
}

function* expandDrinks(order: Order) {
  function drinkLabel(name: string, index: number) { return `${name} #${index + 1}`; }
  for (const item of order.items) {
    for (let index = 0; index < (item.quantity ?? 1); index++) yield drinkLabel(item.name, index);
  }
}

function* (orders: Order[]) {
  function ready(order: Order) { return order.status === "ready"; }
  for (const order of orders) if (ready(order)) yield order;
}

function retryPickup(order: Order) {
  function resetPickup() { order.status = "queued"; order.note = "retry at counter"; return order; }
  return resetPickup();
}

function* missingDrinks(orders: Order[]) {
  function empty(order: Order) { return order.items.length === 0; }
  for (const order of orders) if (empty(order)) yield order;
}

function* (orders: Order[]) {
  function archiveEntry(order: Order) { return `${order.id}: ${order.customer} (${order.status})`; }
  for (const order of orders) yield archiveEntry(order);
}

function printReceipt(order: Order) {
    function itemCount() { return order.items.reduce((sum, item) => sum + (item.quantity ?? 1), 0); }
    return `${order.customer}: ${itemCount()} drinks`;
  }

function* pickupNotifications(orders: Order[]) {
    function notification(order: Order) { return `Pickup for ${order.customer} at ${order.note || "counter"}`; }
    for (const order of orders) yield notification(order);
  }

function* (orders: Order[]) {
    function delivery(order: Order) { return { customer: order.customer, drinks: order.items, note: order.note }; }
    for (const order of orders) if (order.status === "ready") yield delivery(order);
  }

function* trackBatch(orders: Order[]) {
  const collectTicket = (((order: Order) => {
    function batchLabel() { return `${order.id}: ${order.items.length} lines`; }
    return batchLabel();
  }));
  for (const order of orders) yield collectTicket(order);
}

function internalTicket(order: Order) {
    function dispatchLabel() { return `${order.customer}: ready for collection`; }
    return dispatchLabel();
  }

function formatMoney(amount: number, currency = "EUR"): string {
  return `${currency} ${amount.toFixed(2)}`;
}

function* itemLines({ items }: Order): Generator<string> {
  function describe({ name, quantity = 1 }: OrderItem): string {
    return `${quantity} x ${name}: ${receiptFormatters.money(Recipe.price(name) * quantity)}`;
  }
  for (const item of items) yield describe(item);
}

function* (order: Order, discount = 0, ...fees: number[]): Generator<string> {
  yield `Total: ${receiptFormatters.money(priceOrder(order, discount, ...fees))}`;
  if (order.note) yield `Note: ${order.note}`;
}
